"""Note113 : test sauvegarde sans maintien involontaire du mute, diagnostics conserves."""
import argparse,json,pathlib,re,shutil,subprocess,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[1];STAMP='2026-10-17-quick-save-test-2'
JS='''// Note113 : candidat isole ; le loader repeat porte le correctif apres les init UI.
(()=>{const a=window.MCFlasherApp,b=window.MCBuilder,d=window.MCQuickSaveLatch,n=x=>typeof x==='string'?parseInt(x,16):x,h=x=>(x>>>0).toString(16).padStart(8,'0'),hash=x=>b.hex(b.sha256(x));
window.MCQuickSaveLatchReady=window.MCQuickSaveReady.then(()=>{const previous=window.MCMidiBankCompose;window.MCMidiBankCompose=(...args)=>{const prior=previous(...args);if(!prior.tweaks.some(t=>t.id==='sample-wizard'))return prior;const latch=prior.tweaks.some(t=>t.writes?.some(w=>0x40000400+w.off<=0x401487ec&&0x401487ee<=0x40000400+w.off+w.new.length/2));if(!latch)return prior;const r={...prior,tweaks:JSON.parse(JSON.stringify(prior.tweaks)),refMods:{...prior.refMods}},owner=r.tweaks.find(t=>t.id==='control-all-beat-repeat');if(!owner)throw Error('Quick save latch test: select Control All Beat Repeat');const origin=(n(owner.append.dest)+owner.append.size+15)&~15,jump='4ef9'+h(origin)+'4e71'.repeat(22),changed=new Set([owner]);let count=0;
for(const t of r.tweaks)for(const p of t.append?.parts||[]){if(!p.hex)continue;const i=p.hex.indexOf(d.old);if(i<0)continue;if(p.hex.indexOf(d.old,i+1)>=0)throw Error('Quick save latch: ambiguous body');p.hex=p.hex.slice(0,i)+jump+p.hex.slice(i+d.old.length);changed.add(t);count++;}if(count!==1)throw Error('Quick save latch: body guard');owner.append.parts.push({dest:'0x'+h(origin),hex:d.hex});owner.append.size=origin+d.hex.length/2-n(owner.append.dest);owner.symbols.qs_latch='0x'+h(origin);const loader=owner.writes.find(w=>0x40000400+w.off===window.MCBeatRepeat.boot.at);if(!loader)throw Error('Quick save latch: loader missing');const boot=b.fromHex(loader.new);new DataView(boot.buffer).setUint32(window.MCBeatRepeat.boot.symbols.br_boot_size,owner.append.size,false);loader.new=b.hex(boot);
const c=b.parseContainer(b.unwrap(args[1]).stream),section=c.sections.find(s=>s.id===3),stock=b.aplibDepack(c.blob.subarray(section.off,section.off+section.size)).data;for(const t of changed){delete t.append.compressed_hex;delete t.append.stored;r.refMods[t.id]={w:hash(b.writesBytes(t)),p:hash(b.buildPayload(t.append,args[2],stock))};}let source=0x40000400+stock.length;for(const t of r.tweaks.filter(t=>t.append&&t!==owner))source=Math.max(source,n(t.append.at))+b.buildPayload(t.append,args[2],stock).length;owner.append.at='0x'+h(source);const moved=b.fromHex(loader.new);new DataView(moved.buffer).setUint32(window.MCBeatRepeat.boot.symbols.br_boot_source,source,false);loader.new=b.hex(moved);r.refMods[owner.id]={w:hash(b.writesBytes(owner)),p:hash(b.buildPayload(owner.append,args[2],stock))};return r;};});})();
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();old=json.loads((ROOT/'docs/flasher-quick-save-test/quick-save-data.js').read_text().split('=',1)[1].strip().rstrip(';'));w=json.loads((ROOT/'firmware/wizard-catalogue.json').read_text())['variants']['0']['wizard'];origin=(int(w['append']['dest'],16)+w['append']['size']+15)&~15
 cross=next(c for c in ('m68k-linux-gnu-','m68k-elf-') if shutil.which(c+'as'))
 with tempfile.TemporaryDirectory() as tmp:
  p=pathlib.Path(tmp);subprocess.run([cross+'as','-march=cfv4e','-o',str(p/'x.o'),str(ROOT/'tools/machines/quick_save/latch.s')],check=True);(p/'x.ld').write_text(f"SET_HELD = {old['symbols']['set_held']}; SECTIONS {{ .text {origin:#x} : {{ *(.text) }} }}");subprocess.run([cross+'ld','-T',str(p/'x.ld'),'-o',str(p/'x.elf'),str(p/'x.o')],check=True);subprocess.run([cross+'objcopy','-O','binary',str(p/'x.elf'),str(p/'x.bin')],check=True);code=(p/'x.bin').read_bytes()
 data=dict(at=old['at'],size=old['size'],old=old['hex'],hex=code.hex());target=ROOT/'docs/flasher-quick-save-test';files={'quick-save-latch.js':JS,'quick-save-latch-data.js':'window.MCQuickSaveLatch='+json.dumps(data,separators=(',',':'))+';\n'}
 files['diagnostic-release.js']='window.MC_RELEASES='+json.dumps([dict(version='Quick-save-test.2',date='2026-10-17',changes=[dict(en='Quick save releases the unintended mute latch when opening its save menu. Diagnostics retained; main unchanged. Keep Control All Beat Repeat selected in this test.',fr='La sauvegarde rapide libere le mute verrouille involontaire lors de son ouverture. Diagnostics conserves ; principal inchange. Garder Control All Beat Repeat selectionne dans ce test.')])],ensure_ascii=False)+';\n'
 for name,text in files.items():
  if a.check:assert (target/name).read_text(encoding='utf-8').replace('\r\n','\n')==text,name
  else:(target/name).write_text(text,encoding='utf-8')
 s=(target/'index.html').read_text(encoding='utf-8');s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s)
 if 'src="quick-save-latch.js?' not in s:s=s.replace('</body>',f'<script src="quick-save-latch-data.js?v={STAMP}"></script><script src="quick-save-latch.js?v={STAMP}"></script></body>')
 s=re.sub(r'(<main class="wrap fl">)<p>.*?</p>',lambda m:m.group(1)+'<p><strong data-l="en">Quick-save test 2:</strong><strong data-l="fr">Test sauvegarde rapide 2 :</strong> <span data-l="en">Hold FUNCTION + SETTINGS. After closing the save menu and releasing FUNCTION, its light and momentary mute mode should clear. Other SETTINGS shortcuts remain unchanged. Keep Control All Beat Repeat selected for this diagnostic test. Diagnostics retained; main unchanged.</span><span data-l="fr">Maintenir FUNCTION + SETTINGS. Apres fermeture du menu sauvegarde et relachement de FUNCTION, sa LED et le mute momentane doivent se terminer. Autres raccourcis SETTINGS conserves. Garder Control All Beat Repeat selectionne pour ce test diagnostic. Diagnostics conserves ; principal inchange.</span></p>',s,count=1,flags=re.S)
 if not a.check:(target/'index.html').write_text(s,encoding='utf-8')
 else:assert (target/'index.html').read_text(encoding='utf-8')==s
 print('PASS quick save latch',len(code),'octets, test seulement')
if __name__=='__main__':main()

